/* ---------- Utilitários ---------- */
function monthKey(d){ return d.slice(0,7); }
function fmtMonthLabel(ym){
  const [y,m] = ym.split('-').map(Number);
  const names = ["Janeiro","Fevereiro","Março","Abril","Maio","Junho","Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"];
  return `${names[m-1]}/${y}`;
}
function todayISO(){ return new Date().toISOString().slice(0,10); }
function uid(){ return Math.random().toString(36).slice(2,10); }

function toast(msg){
  let t = document.getElementById('toast');
  if(!t){
    t = document.createElement('div');
    t.id = 'toast';
    t.className = 'toast';
    document.body.appendChild(t);
  }
  t.textContent = msg;
  t.classList.add('show');
  clearTimeout(toast._h);
  toast._h = setTimeout(()=> t.classList.remove('show'), 2400);
}

// openModal(html, {largo:true}) = janela mais larga (editores com muito conteúdo)
function openModal(html, opts){
  document.getElementById('modalBox').classList.toggle('largo', !!(opts && opts.largo));
  document.getElementById('modalBox').innerHTML = html;
  document.getElementById('modalBg').classList.add('active');
}
function closeModal(){
  document.getElementById('modalBox').classList.remove('largo');
  document.getElementById('modalBg').classList.remove('active');
  document.getElementById('modalBox').innerHTML = '';
}

/* ---------- Autenticação / sessão ---------- */
// Toda página deve ter no <body>: <div id="sidebarMount"></div> <div id="modalBg" class="modal-bg"><div id="modalBox" class="modal-box"></div></div>
// e chamar guardStaff('home') ou guardAthlete('roteiros') logo no início do seu <script>.

async function getSessionUser(){
  const { data } = await sb.auth.getSession();
  return data?.session?.user || null;
}

async function loadProfile(userId){
  const { data } = await sb.from('profiles').select('*').eq('id', userId).single();
  return data ? {id:data.id, nome:data.nome, role:data.role} : {id:userId, nome:'', role:'geral'};
}

// Página inicial de cada tipo de login: equipe → home, atleta/parceiro → portal do atleta,
// creator do Programa Creators → portal /creators (ele nunca entra nas páginas da equipe).
function paginaInicialDoPerfil(profile){
  return profile.role === 'atleta' ? 'atleta-home' : profile.role === 'creator' ? 'creators' : 'home';
}

// Chame no topo de cada página da EQUIPE. Redireciona pro login se não tiver
// sessão, ou pro portal certo se quem logou for atleta ou creator.
async function guardStaff(activeId){
  const user = await getSessionUser();
  if(!user){ location.href = 'login'; return null; }
  const profile = await loadProfile(user.id);
  if(profile.role === 'atleta' || profile.role === 'creator'){ location.href = paginaInicialDoPerfil(profile); return null; }
  await carregarEquipes();
  renderStaffSidebar(activeId, profile);
  return { user, profile };
}

// Chame no topo de cada página do ATLETA.
async function guardAthlete(activeId){
  const user = await getSessionUser();
  if(!user){ location.href = 'login'; return null; }
  const profile = await loadProfile(user.id);
  if(profile.role !== 'atleta'){ location.href = paginaInicialDoPerfil(profile); return null; }
  const { data: athleteRow } = await sb.from('athletes').select('*').eq('auth_user_id', user.id).single();
  const athlete = athleteRow ? mapAthleteFromDB(athleteRow) : null;
  await carregarEquipes();
  renderAthleteSidebar(activeId, athlete);
  return { user, profile, athlete };
}

async function logout(){
  await sb.auth.signOut();
  location.href = 'login';
}

/* ---------- Sidebar (mesmo HTML/CSS pros dois tipos de usuário) ---------- */
function sidebarShell(navHtml, footerHtml, extra){
  extra = extra || {};
  return `
    <div class="mobile-top">
      <button class="mt-btn" onclick="abrirMenu()" aria-label="Abrir menu">${ICONS.menu}</button>
      <img class="mt-logo" src="${LOGO_SIMBOLO_BRANCO}" alt="FourLab">
      <span class="mt-title">${escHtml(extra.titulo || '')}</span>
    </div>
    <div class="menu-backdrop" onclick="fecharMenu()"></div>
    <aside class="sidebar">
      <div class="sidebar-logo"><img src="${LOGO_SIMBOLO_BRANCO}" alt="FourLab"></div>
      <nav class="sidebar-nav">${navHtml}</nav>
      <div class="sidebar-footer">${footerHtml}</div>
    </aside>
    ${extra.bottomNav ? `<nav class="bottom-nav">${extra.bottomNav}</nav>` : ''}`;
}
// Menu lateral no celular
function abrirMenu(){ document.body.classList.add('menu-aberto'); }
function fecharMenu(){ document.body.classList.remove('menu-aberto'); }

function navItemHtml(activeId, t){
  return `<a class="nav-btn ${activeId===t.id?'active':''}" href="${t.href}" data-nav="${t.id}"><span class="ic" style="position:relative;">${t.ic}</span><span class="label">${t.label}</span></a>`;
}

/* ---------- Avisos: bolinha de "novo" no menu ----------
   A última vez que a pessoa abriu a aba Avisos fica guardada neste navegador. */
function avisosVistosEm(){ try{ return localStorage.getItem('avisosVistosEm') || ''; }catch(e){ return ''; } }
function marcarAvisosComoVistos(){ try{ localStorage.setItem('avisosVistosEm', new Date().toISOString()); }catch(e){} }
async function marcarAvisosNovosNoMenu(){
  const visto = avisosVistosEm();
  let q = sb.from('avisos').select('id', {count:'exact', head:true});
  if(visto) q = q.gt('created_at', visto);
  const { count, error } = await q;
  if(error || !count) return;
  document.querySelectorAll('[data-nav="avisos"] .ic').forEach(ic=>{
    if(!ic.querySelector('.nav-dot')) ic.insertAdjacentHTML('beforeend', `<span class="nav-dot" title="${count} aviso(s) novo(s)"></span>`);
  });
}

function renderStaffSidebar(activeId, profile){
  const nav = STAFF_NAV.map(navItemHtml.bind(null, activeId)).join('');
  const titulo = (STAFF_NAV.find(t=>t.id===activeId)||{}).label || 'FourLab';
  const footer = `${profile?.nome || 'Usuário'} · ${profile?.role === 'chefia' ? 'Chefia' : 'Geral'}
    <button onclick="logout()" style="display:flex; align-items:center; gap:5px; margin-top:6px; background:none; border:none; color:rgba(255,255,255,0.7); font-size:11px; cursor:pointer; text-decoration:underline; padding:0;">${ICONS.sair} Sair</button>`;
  document.getElementById('sidebarMount').innerHTML = sidebarShell(nav, footer, {titulo});
  if(activeId !== 'avisos') marcarAvisosNovosNoMenu();
}

function renderAthleteSidebar(activeId, athlete){
  // Atletas veem "Meus roteiros"; profissionais parceiros veem "Meus textos (blog)"
  const categoria = isProfissional(athlete) ? 'profissional' : 'equipe';
  const tabs = ATLETA_NAV.filter(t=> (t.id !== 'vendas' || temAcessoVendas(athlete)) && (!t.so || t.so === categoria));
  const nav = tabs.map(navItemHtml.bind(null, activeId)).join('');
  const titulo = (ATLETA_NAV.find(t=>t.id===activeId)||{}).label || 'FourLab';
  // celular: barra de ícones embaixo, como num app
  const bottomNav = tabs.map(t=> `<a class="${activeId===t.id?'active':''}" href="${t.href}" data-nav="${t.id}"><span class="ic">${t.ic}</span>${t.curto||t.label}</a>`).join('');
  document.body.classList.add('tem-bottom-nav');
  const footer = `${athlete ? escHtml(athlete.name) : 'Atleta'} · ${athlete ? escHtml(athlete.team) : ''}
    <button onclick="logout()" style="display:flex; align-items:center; gap:5px; margin-top:6px; background:none; border:none; color:rgba(255,255,255,0.7); font-size:11px; cursor:pointer; text-decoration:underline; padding:0;">${ICONS.sair} Sair</button>`;
  document.getElementById('sidebarMount').innerHTML = sidebarShell(nav, footer, {titulo, bottomNav});
  if(activeId !== 'avisos') marcarAvisosNovosNoMenu();
}

